BEGIN;
-- ภาพยนตร์ skills: a skill with output 'film' carries a "directive" (English guidance for the film
-- planner). An episode keeps up to 3 chosen film skills in its document; the planner applies them.
ALTER TABLE skills ADD COLUMN IF NOT EXISTS directive text NOT NULL DEFAULT '' CHECK (char_length(directive) <= 1500);
ALTER TABLE skills DROP CONSTRAINT IF EXISTS skills_output_check;
ALTER TABLE skills ADD CONSTRAINT skills_output_check CHECK (output IN ('video_9_16','video_16_9','storyboard','image_set','film'));

INSERT INTO skills (id, user_id, name, description, icon, steps, inputs, output, directive, sort_order) VALUES
 ('c0000000-0000-4000-8000-000000000001', NULL, 'มุมกล้องหนังแอ็กชัน', 'ช็อตกว้างบอกตำแหน่ง สลับช็อตกระชับตอนปะทะ แทรกช็อตมือ/เท้า มุมต่ำให้ฮีโร่ ทิศทางการเคลื่อนที่ต่อเนื่องข้ามคัต', 'zap',
  '["เปิดแต่ละฉากด้วยช็อตกว้างบอกตำแหน่งตัวละคร","ปะทะใช้ tracking / handheld สลับช็อตกระชับและ insert","ปิดฉากด้วยช็อตนิ่งให้จังหวะลง"]', '["character"]', 'film',
  'Action coverage. Open each action scene with one wide shot that shows where everyone stands. During fights and chases alternate medium and medium-close shots; use tracking for chases and handheld for close combat, static for the moment before the hit. Put the camera slightly below eye level for the hero''s power beats, slightly above for a defeated opponent. Insert short close shots of hands, feet, a weapon or an impact between beats (4-5 s). Keep screen direction: a character moving left-to-right keeps moving left-to-right across cuts unless a shot shows the turn. End each action scene on a static medium or wide hold so the beat lands. Audio: punchy impacts, whooshes, breathing, a driving percussion score.', 10),
 ('c0000000-0000-4000-8000-000000000002', NULL, 'ฟิล์มนัวร์ / ระทึกขวัญ', 'แสงต่ำคอนทราสต์สูง เงาจากบานเกล็ด ซิลูเอตต์ที่ประตู มุมเอียงเฉพาะตอนไม่ไว้ใจ ดันกล้องช้า ๆ ตอนเฉลย', 'moon',
  '["ตั้งแสงต่ำ แหล่งแสงเดียว เงาเข้ม","จัดเฟรมผ่านเงา กระจก ประตู","ดันกล้องเข้าเฉพาะจังหวะเฉลย"]', '["character","style"]', 'film',
  'Noir thriller look. Low-key lighting from one hard motivated source (a desk lamp, a street light through blinds, a doorway), deep shadows, faces half in shadow, venetian-blind or window-frame shadow patterns on walls and faces, cigarette-smoke or dust haze in the light beam. Frame through things: door gaps, reflections in glass or mirrors, rain-streaked windows. Silhouettes in doorways for entrances. Mostly static frames and slow push ins; use a slight dutch tilt (10-15 degrees) only for moments of suspicion or betrayal. Reveal information by a slow push in or a rack focus from foreground to background. Palette: desaturated, cold shadows, warm practical lights. Audio: room tone, ticking clock, distant sirens, a low muted brass or bass drone.', 11),
 ('c0000000-0000-4000-8000-000000000003', NULL, 'หนังรักโทนอบอุ่น', 'แสงอบอุ่นช่วงโกลเด้นอาวร์ โคลสอัพเลนส์ 85mm หลังเบลอ ช็อตสองคนมีพื้นที่ว่าง ดันกล้องช้า ๆ ตอนจุดพีคทางอารมณ์', 'heart',
  '["แสงอบอุ่นจากหน้าต่าง/โกลเด้นอาวร์","ช็อตสองคนเว้นพื้นที่ แล้วตัดเข้าโคลสอัพ","ดันกล้องเข้าเฉพาะประโยคสำคัญ"]', '["character"]', 'film',
  'Warm romance. Golden-hour sun, window daylight or warm practical lamps; soft backlight and rim light on hair; gentle haze. Two-shots keep breathing space between the pair at the start of a scene and bring them closer in frame as the scene warms up. Close-ups on an 85 mm lens with a very shallow depth of field, soft foreground framing (a shoulder, a curtain, a cup). Eyelines meet across cuts. Camera mostly static or a very slow push in; save the push in for the emotional turning line. No handheld, no fast moves. Insert small details: fingers almost touching, a glance down, a smile held back. Audio: soft ambience, quiet piano or acoustic guitar.', 12),
 ('c0000000-0000-4000-8000-000000000004', NULL, 'เฟรมสมมาตรโทนพาสเทล', 'จัดเฟรมสมมาตรกลางภาพ ภาพแบนนิ่ง แพนด้านข้างตามตัวละคร โทนสีพาสเทล จังหวะตลกแบบนิ่ง ๆ', 'layout-grid',
  '["วางตัวละครกึ่งกลาง เฟรมสมมาตร","ใช้กล้องนิ่งหรือแพน/แทร็กด้านข้างเท่านั้น","คุมโทนสีพาสเทลทั้งตอน"]', '["style"]', 'film',
  'Symmetrical storybook framing (this overrides the usual off-centre composition and the symmetrical-room cliche rule). Subjects stand dead centre in perfectly symmetrical, flat, front-on frames, the camera at eye level square to the set. Movement is only static, a lateral tracking shot that slides sideways with a walking character, or a whip-free straight pan; never handheld or orbit. Production design in a coordinated pastel palette (pink, mint, mustard, powder blue), tidy props arranged in rows, signage and uniforms. Characters perform deadpan with little facial movement; comic beats come from cutting to a static insert or a centred reaction. Audio: quirky light score with harpsichord, pizzicato strings or whistling.', 13),
 ('c0000000-0000-4000-8000-000000000005', NULL, 'สารคดี / แฮนด์เฮลด์สมจริง', 'กล้องมือถือแบบสังเกตการณ์ แสงธรรมชาติ ตัวละครไม่รู้ตัวว่ามีกล้อง เปลี่ยนโฟกัสหาจุดสนใจ', 'video',
  '["กล้อง handheld เลนส์ 35mm แสงที่มีอยู่จริง","ถ่ายแบบสังเกตการณ์ ไม่จัดท่าทาง","ใช้ rack focus แทนการตัดบ่อย"]', '["character"]', 'film',
  'Observational documentary. Handheld camera with gentle natural sway, 35 mm lens, shoulder height, as if a camera operator is in the room; characters never look into the lens and do not pose. Available light only (windows, overhead fluorescents, street light), slightly imperfect exposure. Frame a little loose and off-centre, sometimes partly blocked by people or objects in the foreground. Prefer one longer observational shot with a rack focus between two people or between a person and an object over many cuts. Interviews or confessions: medium close-up, subject on a third, looking just off-camera at an unseen interviewer. Audio: real room sound, overlapping chatter, no score or a sparse one.', 14),
 ('c0000000-0000-4000-8000-000000000006', NULL, 'สยองขวัญ', 'ค้างภาพนิ่งนาน พื้นที่ว่างด้านหลังตัวละคร แสงน้อย เฉลยสิ่งผิดปกติที่ฉากหลัง ดันกล้องช้ามาก ๆ', 'eye',
  '["ค้างช็อตนิ่งนาน ทิ้งพื้นที่ว่างให้คนดูระแวง","ให้สิ่งผิดปกติปรากฏที่ฉากหลังหรือในเงา","เงียบก่อน แล้วค่อยมีเสียงกระแทก"]', '["character","style"]', 'film',
  'Slow-burn horror. Long static holds and very slow push ins; leave large empty negative space behind or beside the character (a dark doorway, a hallway, a window) so the audience scans it. Under-lit rooms with one weak practical light, deep blacks, cold desaturated colour. Reveal threats in the background, out of focus or half in shadow, never centred and never fully lit; show less rather than more. Use point-of-view framing from behind objects (through a gap in a door, between stair rails) to suggest something watching. Wide lens (24 mm) close to a frightened face for unease. Audio: near silence, room tone, creaks and breathing, a low drone, then one sharp sting only at the scare.', 15),
 ('c0000000-0000-4000-8000-000000000007', NULL, 'เปิดเรื่องแบบมหากาพย์', 'ช็อตเปิดมุมสูง crane up เห็นสเกลใหญ่ ตัวละครเล็กในภูมิประเทศ ซิลูเอตต์ตัดกับท้องฟ้า', 'mountain',
  '["เปิดด้วยช็อตมุมสูงหรือ crane up เห็นภูมิประเทศ","ให้ตัวละครเล็กในเฟรมเพื่อบอกสเกล","ตามด้วยช็อตมุมต่ำซิลูเอตต์ตัดฟ้า"]', '["character"]', 'film',
  'Epic scale. Open the episode and each new location with one grand establishing shot: an aerial glide or a crane up revealing the landscape, the character small in the frame to show scale (this overrides the "tiny figure" cliche rule). Follow with a low-angle medium shot of the hero silhouetted against a bright sky. Use wide lenses (24 mm) for landscapes and armies, long lenses (85 mm) to compress crowds or distant riders. Dramatic natural light: sunrise or sunset backlight, dust or mist in the air, moving cloud shadows. Keep moves slow and majestic; one move per shot. Audio: wind, distant horns or drums, a swelling orchestral score.', 16),
 ('c0000000-0000-4000-8000-000000000008', NULL, 'ดราม่าบทสนทนา', 'ถ่ายบทสนทนาแบบช็อต/รีเวิร์ส ข้ามไหล่ เน้นสีหน้าคนฟัง แทรกช็อตมือ ดันกล้องเฉพาะประโยคที่เปลี่ยนเรื่อง', 'messages-square',
  '["เปิดด้วยช็อตสองคนสั้น ๆ","ถ่ายข้ามไหล่สลับกัน เน้นสีหน้าคนฟัง","ดันกล้องเข้าเฉพาะประโยคหักมุม"]', '["character","voice"]', 'film',
  'Dialogue drama coverage. Start a conversation with a short two-shot that shows where both people sit or stand, then cut to over-the-shoulder shots and singles that alternate between them, matching eyelines and keeping both on their own side of the frame (180-degree rule). Lenses 50-85 mm, shallow focus on the face that matters. Give the listener''s reaction its own shot when a hard line lands. Add inserts of hands, a phone, a ring or a cup between lines to show subtext. Camera static during the exchange; one slow push in only on the line that turns the scene. Audio: room tone, small foley (cup on table, chair creak), score only after the turning line.', 17),
 ('c0000000-0000-4000-8000-000000000009', NULL, 'ดราม่าเทคสมจริง', 'ถ่ายข้ามไหล่โดยให้ไหล่เบลอกินเฟรมเยอะ ถ่ายย้อนแสงหน้าต่าง กล้องลอยแบบแฮนด์เฮลด์ จัดคนเป็นชั้นลึกในออฟฟิศ แทรกช็อตมือถือ/แล็ปท็อป โทนสีหม่นมีเกรน', 'users',
  '["ถ่ายข้ามไหล่โดยให้ไหล่/หัวเบลอกินฉากหน้า 1/3-1/2 ของเฟรม","หันกล้องเข้าหน้าต่าง ให้ตัวละครย้อนแสง มีแฟลร์","จัดกลุ่มคนเป็นชั้นลึก เปิดงานเลี้ยงด้วยช็อตมุมบนลงล่าง","แทรกช็อตมือกับโทรศัพท์/แล็ปท็อป คุมโทนหม่นมีเกรน"]', '["character"]', 'film',
  'Naturalistic tech-drama look, shot like a real camera operator in the room. Dirty over-the-shoulder framing: a soft, out-of-focus shoulder or back of a head fills a third to half of the frame in the foreground, the other person sharp on the opposite third. Shoot into bright windows: subjects backlit with blown-out daylight, soft lens flare and rim light, faces lit only by bounce. Lenses 35-50 mm at eye level or just below, a gentle handheld float or static; never glossy or symmetrical. Group scenes are staged in depth: people layered from foreground to background in offices and kitchens, someone partly cut by the frame edge. Use one top-down overhead shot of a table or crowd to open a gathering. Cut to tight inserts of hands on phones, laptops and cups between lines. Occasional screen-glow shots: code or UI reflected over a face, or a face seen through glass. Colour: muted, low-contrast, soft greens and greys by day, warm tungsten lamps at night, fine film grain. Audio: room tone, office murmur, keyboard taps, a sparse modern score.', 18)
ON CONFLICT (id) DO NOTHING;
COMMIT;
